import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第五百四十四章 让家庭受到伤害的原因","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/544第五百四十四章 让家庭受到伤害的原因.md","filePath":"meditation/巴利文大藏经/544第五百四十四章 让家庭受到伤害的原因.md"}'),o={name:"meditation/巴利文大藏经/544第五百四十四章 让家庭受到伤害的原因.md"};function r(n,p,i,s,d,c){return _(),e("div",null,p[0]||(p[0]=[a('<h1 id="第五百四十四章-让家庭受到伤害的原因" tabindex="-1">第五百四十四章 让家庭受到伤害的原因 <a class="header-anchor" href="#第五百四十四章-让家庭受到伤害的原因" aria-label="Permalink to &quot;第五百四十四章 让家庭受到伤害的原因&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部42相应9经/家经(村长相应/处篇/如来记说)</p><p>有个时候，佛陀与僧团行脚、游走到憍萨罗国的那烂陀，并住在那烂陀波婆离迦的庵罗林之中。那个时候，那烂陀当地稻田中的水稻患上了白枯病，这导致当地稻谷的产量大幅度的降低，粮食越来越少，很多人都吃不饱饭了，当地大量的人都靠挖掘野菜来充饥了。</p><p>那时，外教宗教领袖尼乾陀若提子与他的信众们也住在那烂陀，有一天，外教宗教领袖尼乾陀若提子的弟子，一位制造刀具的村长来到尼乾陀若提子的住处，他顶礼尼乾陀若提子后，就在一旁坐下，尼乾陀若提子对这位村长说：“村长！你等下去乔达摩那里，驳斥他和他所说的法，如果你辩论战胜了乔达摩，那么你就能获得广大的名声，无数多的人就会说：「村长辩论胜过了乔达摩（佛陀），简直不简单呀，乔达摩可是被很多人尊为已经证悟无上正等正觉的人呀！看来村长的见解比乔达摩的还要高明，我们要皈依村长，并跟着他修行」。”</p><p>这位村长说：“尊师，我如何才能辩论胜过乔达摩呢？”</p><p>外教宗教领袖尼乾陀若提子说：“村长，你这样去问乔达摩：「世尊，您对世间人或众生讲说种种的法门，是为了救济和帮助世间人或众生吗？是因为同情和怜悯世间人或众生吗？是为了保护世间人或众生不再被烦恼和痛苦折磨吗？」</p><p>村长，如果乔达摩回答：「村长，如来对世间人或众生说法，确实是为了救济和帮助他们，确实是因为同情和怜悯他们，确实是为了保护他们不再被烦恼和痛苦折磨。」你就这样驳斥乔达摩：「世尊，那我有个问题就不明白了，既然您是为了救济和帮助世间人或众生而对他们说法，既然您是因为同情和怜悯世间人或众生而对他们说法，既然您是为了保护他们不被烦恼和痛苦折磨而对他们说法，那为什么现在那烂陀的水稻患上了白枯病，粮食减产了，大家都没有饭吃了，都闹饥荒了，您和您的出家弟子们，还在中午的时候挨家挨户，不分贫富贵贱的家庭化缘饭食呢？那烂陀的人都没有饭吃了，都要靠挖野菜充饥了，您们现在这么多人还在向他们索要食物，并且您们什么也不干，既不种植粮食，也不筹集粮食，光是向别人要粮食，您们这样的行为是救济帮助世间人或众生吗？您们这样的行为是同情和怜悯世间人或众生吗？您们这样的行为能够让世间人或众生解除烦恼和痛苦吗？我从您们的行为上就知道，世尊您刚才的那种为世间人或众生谋福利的说法，不过是一种浮夸的假话，是一种为了获得信众供养的假话，因此我可以断言：世尊您和您出家弟子们聚集的僧团是损害俗世家庭利益的人和团体，您与您出家弟子们聚集的僧团是伤害、祸害家庭利益的人和团体，我这样说是有我的道理的，现在那烂陀闹饥荒，您们什么都不做，光是向那烂陀的人化缘饭食，本来粮食就少，您们还去让那烂陀的人给您们粮食，他们自己的粮食都不够吃，但是又害怕不供养您们饭食会让自己下堕到恶道、地狱道、不幸痛苦的地方中受苦，只好硬着头皮将自己本来就不多的口粮给了您们，这样他们自己就要饿肚子了，世尊，您自己扪心自问，您们是不是在损害、伤害、祸害俗世家庭的利益呢？从您们的行为上，我就知道，实际上您们也只是自私自利的人，那些所谓的什么为了救济帮助世间人或众生，那些所谓的什么是为了同情和怜悯世间人或众生，那些所谓的是为了解除世间人或众生的烦恼和痛苦的等等说词，都是些大话和假话，是为了获得信众的供养才编出来的假话！世尊，难道不是这样的吗？您还有什么话要对我说的吗？」</p><p>村长，只要你这样的去问乔达摩，他绝对会处于两难的境地之中。乔达摩，必定既想回答你的问题，又不知道该如何的回答你的问题，就如同吃饭的时候被食物卡住、噎住，既不能将吃到嘴中的食物吐出来，也不能将食物咽下去，吞到肚子里面去。”</p><p>这位村长说：“尊师，您说的太好了，我确信乔达摩，无法回应这些问题，尊师，还有个问题哦，如果乔达摩反问：「为什么您的导师尼乾陀若提子也在那烂陀闹饥荒的时候接受当地人的供养呢？难道他也是损害、伤害、祸害俗世家庭利益的人吗？」我该如何回答他呢？”</p><p>外教宗教领袖尼乾陀若提子说：“村长，你不用担心，是你先问乔达摩问题的，如果他问你这样的问题，说明他已经心虚了，他已经不知道该如何回答你的问题了，你就直接反复的说：「恭请世尊您先回答我的问题」如果乔达摩多次的反问刚才你说的那个问题，那就表明你已经辩论胜过他了，如果大众知道你们辩论的过程后都会认为是村长你辩论胜利了，这个你不用担心。村长你只要按我说的去做，你肯定能够辩论胜过乔达摩的。”</p><p>外教宗教领袖尼乾陀若提子嘱咐村长完毕后，这位村长就站起来向右围绕着尼乾陀若提子转圈，以表示他对尼乾陀若提子的最高敬意。之后，这位村长就来到佛陀的住所，他顶礼佛陀后，就在一旁坐下，村长对佛陀说：“世尊，您对世间人或众生讲说种种的法门，是为了救济和帮助世间人或众生吗？是因为同情和怜悯世间人或众生吗？是为了保护世间人或众生不再被烦恼和痛苦折磨吗？”</p><p>佛陀说：“村长，如来对世间人或众生说法，确实是为了救济和帮助他们，确实是因为同情和怜悯他们，确实是为了保护他们不再被烦恼和痛苦折磨。”</p><p>村长说：“世尊，那我有个问题就不明白了，既然您是为了救济和帮助世间人或众生而对他们说法，既然您是因为同情和怜悯世间人或众生而对他们说法，既然您是为了保护他们不被烦恼和痛苦折磨而对他们说法，那为什么现在那烂陀的水稻患上了白枯病，粮食减产了，大家都没有饭吃了，都闹饥荒了，您和您的出家弟子们，还在中午的时候挨家挨户，不分贫富贵贱的家庭化缘饭食呢？那烂陀的人都没有饭吃了，都要靠挖野菜充饥了，您们现在这么多人还在向他们索要食物，并且您们什么也不干，既不种植粮食，也不筹集粮食，光是向别人要粮食，您们这样的行为是救济帮助世间人或众生吗？您们这样的行为是同情和怜悯世间人或众生吗？您们这样的行为能够让世间人或众生解除烦恼和痛苦吗？我从您们的行为上就知道，世尊您刚才的那种为世间人或众生谋福利的说法，不过是一种浮夸的假话，是一种为了获得信众供养的假话，因此我可以断言：世尊您和您出家弟子们聚集的僧团是损害俗世家庭利益的人和团体，您与您出家弟子们聚集的僧团是伤害、祸害家庭利益的人和团体，我这样说是有我的道理的，现在那烂陀闹饥荒，您们什么都不做，光是向那烂陀的人化缘饭食，本来粮食就少，您们还去让那烂陀的人给您们粮食，他们自己的粮食都不够吃，但是又害怕不供养您们饭食会让自己下堕到恶道、地狱道、不幸痛苦的地方中受苦，只好硬着头皮将自己本来就不多的口粮给了您们，这样他们自己就要饿肚子了，世尊，您自己扪心自问，您们是不是在损害、伤害、祸害俗世家庭的利益呢？从您们的行为上，我就知道，实际上您们也只是自私自利的人，那些所谓的什么为了救济帮助世间人或众生，那些所谓的什么是为了同情和怜悯世间人或众生，那些所谓的是为了解除世间人或众生的烦恼和痛苦的等等说词，都是些大话和假话，是为了获得信众的供养才编出来的假话！世尊，难道不是这样的吗？您还有什么要对我说的吗？”</p><p>佛陀说：“村长，那烂陀现在确实在闹饥荒，很多人都没有饭吃，村长，那烂陀不会因为今年闹饥荒，就不继续种植粮食了吧？他们明年还是会继续种植粮食的吧。”</p><p>村长说：“世尊，那是，为了保证明年还有稻谷可以收获，就算那烂陀现在如此的困难，很多人连饭都吃不饱，他们还是会保留下明年种植水稻所用的种子的，毕竟只要有种子在，明年就有丰收稻谷的希望，明年就有解除饥荒的机会。”</p><p>佛陀说：“村长，如果那烂陀的人明年不种植粮食，那烂陀的饥荒能够解除吗？”</p><p>村长说：“世尊，如果那烂陀的人明年不种植粮食，饥荒还会继续下去。”</p><p>佛陀说：“村长，如来忆念过去九十一劫的事情（劫解释，见第一百三十七章），明白没有任何的家庭会因为供养食物给修行人会受到损害、伤害、祸害，就如同种植水稻的人，他们可能会在某个时候欠收粮食，但是他们还是会继续的种植粮食，他们种植粮食的行为就是布施供养，用他们的辛勤劳动来布施供养大地，大地就会反馈他们，让他们获得粮食的丰收，同样的道理，那些世间的富翁、有钱人，那些拥有大量财富、金银珠宝的人，那些拥有大量财产、粮食、房产的家庭，他们的这些财物全部都是从布施供养中获得的，布施供养是获得财富的真正来源，布施供养是获得大量财物的源泉，大量的财富、财物就是由布施供养而获得的，布施供养是财富的真正来源、源泉。财富也可以从控制、约束自己的行为不放逸中来，也就是财富能够从身体行为不做恶事，口不说恶言，内心不生起恶念中来，财富可以从熄灭、灭除贪欲、渴爱中来，财富也可以从受持戒律、不胡作非为、不胡思乱想中来，财富还可以从善行、善言、善念中来。</p><p>村长，损害、伤害、祸害俗世家庭的原因有八种，也就是如果分别满足八种条件，俗世家庭就会受到损害、伤害、祸害。是哪八种原因和条件呢？</p><p>违反国家法律的俗世家庭，国王就会用国家的律法惩罚他们，他们的家庭就会被损害、伤害、祸害，实际上是他们自作自受；</p><p>盗贼会偷盗财物，强盗会抢劫财物，俗世家庭会被盗贼和强盗损害、伤害、祸害；</p><p>火灾会损害、伤害、祸害俗世家庭；</p><p>水灾会损害、伤害、祸害俗世家庭；</p><p>存储的钱财无缘无故的消失不见会损害、伤害、祸害俗世家庭；</p><p>策划、计划、经营各项事业或生意失败会损害、伤害、祸害俗世家庭；</p><p>家里面出了乱用钱财、好吃懒做、只知道享乐的败家子，这个败家子就会损害、伤害、祸害俗世家庭；</p><p>家里面的顶梁柱、有本事、有能力、挣钱的人生病、死亡会损害、伤害、祸害俗世家庭，这个原因和条件也可以说成是无常会损害、伤害、祸害俗世家庭，什么是无常呢？就是随时在变化，无法永远存在，无法永恒保持不变，无法永远的拥有。家里面的顶梁柱、有本事、有能力、挣钱的人无法永远不生病，无法永远不衰老，无法永远不死亡这就是无常。</p><p>村长，这就是损害、伤害、祸害俗世家庭的八种原因和条件。满足这些原因和条件中的任意一条都会损害、伤害、祸害俗世家庭。</p><p>村长，如果如来已经对前来求法的人讲解了损害、伤害、祸害俗世家庭的八种原因和条件后，这些人还是说这样的话：「世尊和世尊出家弟子们聚集的僧团，他们是损害、伤害、祸害俗世家庭的人和团体，他们对世间人或众生说的是假话，他们对世间人或众生说法的目的就是为了获得信众的供养」 那么这些人就会因为自己不正确的见解而远离如来和如来出家弟子们聚集的僧团，他们就有可能接受不正确的见解，而去身体行为做恶事，口说恶言，内心生起恶念，他们就会因为自己恶行、恶言、恶念造出来的罪业而投生到不幸痛苦的地方中受苦，他们就会因为自己恶行、恶言、恶念造出来的罪业而投生到恶道中受苦，甚至于投生到地狱、畜生、饿鬼三恶道中受苦。那都是因为他们没有正确见解的缘故，就如同在漆黑的夜晚走路的人，他们看不见黑暗道路中隐藏的各种泥坑、陡坡、悬崖，他们很可能会摔倒，甚至于跌到悬崖下面去，这时的他们就需要点燃一盏明灯，照亮前行的道路，这样他们才能看见道路周围的事物，避免自己摔倒，避免自己跌落到悬崖下面去，他们恶行、恶言、恶念的行为就是隐藏在黑暗道路中的泥坑、陡坡、悬崖，如来讲说的正法就是照亮他们前行道路的明灯，如来教导他们远离、熄灭、除灭恶行、恶言、恶念，就如同他们在明灯的照耀下能够看清楚泥坑、陡坡、悬崖在什么地方，他们行走的时候就能避开泥坑、陡坡、悬崖，不至于摔倒，或跌落到悬崖下面去。”</p><p>佛陀说法后，这位村长感动的对佛陀说：“世尊，您说的太好了，您说的太妙了，我从来都没有听过如此精妙绝伦的说法，您所说的法犹如将歪斜的东西扶正，将隐藏的东西显现出来，将深奥的义理，浅显易懂的讲说出来，给迷路的人指出正确的道路，在黑暗中点燃火把，让人能够看见周围的事物，避免行走的时候摔倒。世尊，您所说的其他法也是这样的吧，世尊，请您让我皈依您，皈依您的正法，皈依您出家弟子们聚集的僧团吧，我愿意从今天开始，终生都按着您所说的正法去修行，我愿意终生都成为您的在家修行弟子。”</p><p>佛陀点头接受了这位村长的皈依，并将手放在他的头顶上加持他。</p>',32)]))}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
